# ============================================================
# AUTOMATICALLY GENERATED BY CLOUDMOVE MIGRATION ENGINE
# MAIN INFRASTRUCTURE MODULE
# ============================================================

# Network & Isolation Boundaries
resource "aws_vpc" "target_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name        = "cloudmove-target-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.target_vpc.id
  tags = {
    Name = "cloudmove-igw"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.target_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  tags = {
    Name = "cloudmove-public-subnet"
  }
}

resource "aws_subnet" "private_subnet_a" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "cloudmove-private-subnet-a"
  }
}

resource "aws_subnet" "private_subnet_b" {
  vpc_id            = aws_vpc.target_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "${var.aws_region}b"
  tags = {
    Name = "cloudmove-private-subnet-b"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "cloudmove-app-sg"
  description = "Security group for migrated application workloads"
  vpc_id      = aws_vpc.target_vpc.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "cloudmove-app-sg"
  }
}

# Migrated Resource: rabbitmq-kali-live-os (img-live-rabbitmq-kali)
resource "aws_ebs_snapshot_import" "img_live_rabbitmq_kali_import" {
  disk_container {
    description = "Imported disk image for rabbitmq-kali-live-os"
    format      = "VMDK"
    user_bucket {
      s3_bucket = "cloudmove-vm-import-staging"
      s3_key    = "images/rabbitmq-kali-live-os.vmdk"
    }
  }
  role_name = "vmimport"
  tags = {
    Name      = "rabbitmq-kali-live-os-snapshot"
    CMIR_ID   = "img-live-rabbitmq-kali"
    ManagedBy = "CloudMove"
  }
}

resource "aws_ami" "img_live_rabbitmq_kali" {
  name                = "rabbitmq-kali-live-os-ami"
  virtualization_type = "hvm"
  architecture        = "x86_64"
  boot_mode           = "uefi"
  root_device_name    = "/dev/sda1"
  ena_support         = true
  ebs_block_device {
    device_name = "/dev/sda1"
    snapshot_id = aws_ebs_snapshot_import.img_live_rabbitmq_kali_import.id
    volume_size = 50
    volume_type = "gp3"
  }
  tags = {
    Name      = "rabbitmq-kali-live-os-ami"
    CMIR_ID   = "img-live-rabbitmq-kali"
    ManagedBy = "CloudMove"
  }
}

